<?php
use App\Http\Controllers\{CartController,CheckoutController,ContextController,ReviewController,SiteController,WishlistController};
use App\Http\Controllers\Account\AccountController;
use App\Http\Controllers\Admin\{AdminController,BulkProductController,OrderMasterController,PageManagerController,ResourceController};
use App\Http\Controllers\Auth\AuthController;
use Illuminate\Foundation\Auth\EmailVerificationRequest;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Route;
Route::get('/',[SiteController::class,'home'])->name('home');
Route::get('/shop',[SiteController::class,'shop'])->name('shop');
Route::get('/product/{product:slug}',[SiteController::class,'product'])->name('product');
Route::get('/category/{category:slug}',[SiteController::class,'category'])->name('category');
foreach(['collections','new-arrivals','corporate-orders','bulk-orders','franchise','careers','global-network','factory','contact','virtual-tryon','irish-traditional','irish-heritage'] as $page)Route::get('/'.$page,fn()=>(new SiteController)->page($page))->name(str_replace('-','.',$page));
Route::post('/enquiry',[SiteController::class,'inquiry'])->middleware('throttle:10,1')->name('inquiry');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'show'])->name('login');Route::post('/login',[AuthController::class,'login'])->name('login.submit');Route::get('/register',[AuthController::class,'registerForm'])->name('register.form');Route::post('/register',[AuthController::class,'register'])->name('register');Route::get('/forgot-password',[AuthController::class,'forgotForm'])->name('password.request');Route::post('/forgot-password',[AuthController::class,'forgot'])->name('password.email');Route::get('/reset-password/{token}',[AuthController::class,'resetForm'])->name('password.reset');Route::post('/reset-password',[AuthController::class,'reset'])->name('password.update');});
Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::get('/email/verify',fn()=>view('auth.verify'))->middleware('auth')->name('verification.notice');
Route::get('/email/verify/{id}/{hash}',function(EmailVerificationRequest $request){$request->fulfill();return redirect('/account')->with('success','Email verified.');})->middleware(['auth','signed'])->name('verification.verify');
Route::post('/email/verification-notification',function(Request $request){$request->user()->sendEmailVerificationNotification();return back()->with('success','Verification link sent.');})->middleware(['auth','throttle:6,1'])->name('verification.send');
Route::get('/cart',[CartController::class,'index'])->name('cart');Route::post('/cart/{product}',[CartController::class,'add'])->name('cart.add');Route::patch('/cart/{key}',[CartController::class,'update'])->name('cart.update');Route::delete('/cart/{key}',[CartController::class,'remove'])->name('cart.remove');
Route::middleware('auth')->group(function(){Route::get('/checkout',[CheckoutController::class,'show'])->name('checkout');Route::post('/checkout',[CheckoutController::class,'store'])->name('checkout.store');Route::get('/order/{order}/success',[CheckoutController::class,'success'])->name('order.success');Route::get('/account',[AccountController::class,'dashboard'])->name('account.dashboard');Route::get('/account/{section}',[AccountController::class,'section'])->name('account.section');Route::patch('/account/profile',[AccountController::class,'profile'])->name('account.profile');Route::post('/account/addresses',[AccountController::class,'addressStore'])->name('account.address.store');Route::delete('/account/addresses/{address}',[AccountController::class,'addressDelete'])->name('account.address.delete');Route::post('/account/orders/{order}/return',[AccountController::class,'returnStore'])->name('account.return.store');Route::get('/account/orders/{order}/invoice',[AccountController::class,'invoice'])->name('account.invoice');Route::post('/wishlist/{product}',[WishlistController::class,'toggle'])->name('wishlist.toggle');Route::post('/reviews/{product}',[ReviewController::class,'store'])->name('reviews.store');});
Route::prefix('admin')->middleware(['auth','admin'])->name('admin.')->group(function(){Route::get('/',[AdminController::class,'dashboard'])->name('dashboard');Route::get('/bulk-product-upload',[BulkProductController::class,'index'])->name('bulk-upload');Route::post('/bulk-product-upload',[BulkProductController::class,'store'])->name('bulk-upload.store');Route::get('/orders/{type}',[OrderMasterController::class,'index'])->name('order-master');Route::patch('/orders/{type}/{order}',[OrderMasterController::class,'update'])->name('order-master.update');Route::get('/pages',[PageManagerController::class,'index'])->name('pages');Route::post('/pages',[PageManagerController::class,'store'])->name('pages.store');Route::put('/pages/{page}',[PageManagerController::class,'update'])->name('pages.update');Route::post('/trashed-pages/{page}/restore',[PageManagerController::class,'restore'])->name('pages.restore');Route::delete('/trashed-pages/{page}',[PageManagerController::class,'destroy'])->name('pages.destroy');Route::post('/pages/{page}/{action}',[PageManagerController::class,'action'])->name('pages.action');Route::get('/resource/{module}',[ResourceController::class,'index'])->name('resource');Route::post('/resource/{module}',[ResourceController::class,'store'])->name('resource.store');Route::patch('/resource/{module}/{record}',[ResourceController::class,'update'])->name('resource.update');Route::delete('/resource/{module}/{record}',[ResourceController::class,'destroy'])->name('resource.destroy');Route::get('/module/{module}',[AdminController::class,'module'])->name('module');Route::get('/integration-status',\App\Http\Controllers\Admin\IntegrationStatusController::class)->name('integration-status');});
Route::post('/context/company',[ContextController::class,'company'])->middleware('auth')->name('context.company');Route::post('/context/language',[ContextController::class,'locale'])->name('context.language');Route::post('/context/currency',[ContextController::class,'currency'])->name('context.currency');
